{"command":"cat <<'EOF' > main.go
package main

import (
	"bufio"
	"crypto/tls"
	"encoding/json"
	"encoding/xml"
	"fmt"
	"io"
	"net/http"
	"net/url"
	"os"
	"strconv"
	"strings"
	"sync"
	"time"
	"math/rand"
)

type Result struct {
	URL                string `json:"url" xml:"path,attr"` // Wait, XML used <path url=...>
	Code               int    `json:"code" xml:"code,attr"`
	Size               int64  `json:"size" xml:"content_len,attr"`
	IsDirectory        bool   `json:"is_directory" xml:"is_directory,attr"`
	IsListable         bool   `json:"is_listable" xml:"is_listable,attr"`
	RedirectURL        string `json:"redirect_url" xml:"redirect_url,attr"`
	FoundFromListable  bool   `json:"found_from_listable" xml:"found_from_listable,attr"`
}

type XMLResult struct {
    XMLName xml.Name `xml:"dirble_scan"`
    Results []Result `xml:"path"`
}

type Config struct {
	URIs               []string
	Verb               string
	Wordlist           string
	Prefixes           []string
	Extensions         []string
	ExtSub             bool
	ForceExtension     bool
	IgnoreCert         bool
	Timeout            int
	MaxErrors          int
	JSONFile           string
	XMLFile            string
	OutputFile         string
	MaxThreads         int
	WordlistSplit      int
	Throttle           int
	ScanListable       bool
	MaxRecursionDepth  int
	DisableRecursion   bool
	ScrapeListable     bool
	UserAgent          string
	Cookies            []string
	Headers            []string
	Silent             bool
	Verbose            int
	CodeBlacklist      []int
	CodeWhitelist      []int
	NoColor            bool
}

type Scanner struct {
	config Config
	client *http.Client
	results []Result
	resultsMutex sync.Mutex
	wordlist []string
    visited sync.Map
}

func printHelp() {
