			i++
			if i < len(args) {
				content, _ := os.ReadFile(args[i])
				lines := strings.Split(string(content), "\n")
				for _, line := range lines {
					line = strings.TrimSpace(line)
					if line != "" { conf.URIs = append(conf.URIs, line) }
				}
			}
		case "-w", "--wordlist":
			i++
			if i < len(args) { conf.Wordlist = args[i] }
