	const letters = "abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789"
	b := make([]byte, n)
	for i := range b {
		b[i] = letters[rand.Intn(len(letters))]
	}
	return string(b)
}

func (s *Scanner) makeRequest(method, urlStr string) (int, int64, string, string, error) {
	req, err := http.NewRequest(method, urlStr, nil)
	if err != nil { return 0, 0, "", "", err }

	if s.config.UserAgent != "" { req.Header.Set("User-Agent", s.config.UserAgent) }
	for _, h := range s.config.Headers {
		parts := strings.SplitN(h, ":", 2)
		if len(parts) == 2 {
			req.Header.Add(strings.TrimSpace(parts[0]), strings.TrimSpace(parts[1]))
		} else if strings.HasSuffix(h, ";") {
            req.Header.Add(strings.TrimSuffix(h, ";"), "")
        }
	}
    for _, c := range s.config.Cookies {
        parts := strings.SplitN(c, "=", 2)
        if len(parts) == 2 {
            req.AddCookie(&http.Cookie{Name: parts[0], Value: parts[1]})
        }
    }

	resp, err := s.client.Do(req)
	if err != nil { return 0, 0, "", "", err }
	defer resp.Body.Close()

	bodyBytes, _ := io.ReadAll(resp.Body)
	redirect := resp.Header.Get("Location")
	return resp.StatusCode, int64(len(bodyBytes)), string(bodyBytes), redirect, nil
}

func (s *Scanner) scanDirectory(baseURL string, depth int) {
	if depth > s.config.MaxRecursionDepth { return }
    if _, loaded := s.visited.LoadOrStore(baseURL, true); loaded { return }

	notFoundCode, notFoundSize := 404, int64(-1)
	for i := 0; i < 3; i++ {
		code, size, _, _, err := s.makeRequest(s.config.Verb, baseURL+randString(10+i*5))
		if err == nil {
			notFoundCode = code
			notFoundSize = size
		}
	}
	if !s.config.Silent {
		sizeStr := ""
		if notFoundCode != 404 {
			sizeStr = fmt.Sprintf("|SIZE:%d", notFoundSize)
		}
		fmt.Printf("[INFO] Detected nonexistent paths for %s are (CODE:%d%s)\n", baseURL, notFoundCode, sizeStr)
        if depth == 0 {
            fmt.Printf("[INFO] Increasing wordlist-split for initial scan of %s to 8\n", baseURL)
        }
	}

	tasks := make(chan string)
	var wg sync.WaitGroup
    numWorkers := s.config.WordlistSplit
    if depth == 0 { numWorkers = 8 }

	for i := 0; i < numWorkers; i++ {
		wg.Add(1)
		go func() {
			defer wg.Done()
			for word := range tasks {
				s.checkWord(baseURL, word, notFoundCode, notFoundSize, depth)
			}
		}()
	}

	for _, word := range s.wordlist {
		tasks <- word
	}
	close(tasks)
	wg.Wait()
}

func (s *Scanner) checkWord(baseURL, word string, nfCode int, nfSize int64, depth int) {
	variants := []string{}
	if s.config.ExtSub {
		if strings.Contains(word, "%EXT%") {
			for _, ext := range s.config.Extensions {
				variants = append(variants, strings.ReplaceAll(word, "%EXT%", ext))
			}
		} else {
			variants = append(variants, word)
		}
	} else {
        if !s.config.ForceExtension {
            variants = append(variants, word)
        }
		for _, ext := range s.config.Extensions {
			variants = append(variants, word+ext)
		}
	}

    finalVariants := []string{}
    if len(s.config.Prefixes) > 0 {
        for _, p := range s.config.Prefixes {
            for _, v := range variants {
                finalVariants = append(finalVariants, p+v)
            }
        }
    } else {
        finalVariants = variants
    }

	for _, v := range finalVariants {
        if s.config.Throttle > 0 {
            time.Sleep(time.Duration(s.config.Throttle) * time.Millisecond)
        }
		code, size, body, redirect, err := s.makeRequest(s.config.Verb, baseURL+v)
		if err != nil { continue }

		if code == nfCode && size == nfSize { continue }

		if s.isAllowed(code) {
			res := Result{URL: baseURL + v, Code: code, Size: size}

            if (code == 301 || code == 302 || code == 307 || code == 308) && redirect != "" {
                u, _ := url.Parse(baseURL + v)
                target, _ := url.Parse(redirect)
                if target.Path == u.Path + "/" || target.Path == u.Path {
                    res.URL = baseURL + v + "/"
                    res.IsDirectory = true
                    code2, size2, body2, _, err2 := s.makeRequest(s.config.Verb, res.URL)
                    if err2 == nil {
                        res.Code = code2
                        res.Size = size2
                        body = body2
                    }
                }
            }

            if isListable(body) {
                res.IsListable = true
            }

			s.resultsMutex.Lock()
			s.results = append(s.results, res)
			s.resultsMutex.Unlock()

			if !s.config.Silent {
				char := "+"
				if res.IsListable { char = "L" } else if res.IsDirectory { char = "D" }
				fmt.Printf("%s %s (CODE:%d|SIZE:%d)\n", char, res.URL, res.Code, res.Size)
			}

            if res.IsDirectory && !s.config.DisableRecursion {
                s.scanDirectory(res.URL, depth+1)
            }
		}
	}
}

func isListable(body string) bool {
	lower := strings.ToLower(body)
	return strings.Contains(lower, "<title>index of") ||
		strings.Contains(lower, "directory listing for") ||
		strings.Contains(lower, "<h1>index of")
}

func (s *Scanner) run() {
	s.client = &http.Client{
		Timeout: time.Duration(s.config.Timeout) * time.Second,
		Transport: &http.Transport{
			TLSClientConfig: &tls.Config{InsecureSkipVerify: s.config.IgnoreCert},
		},
		CheckRedirect: func(req *http.Request, via []*http.Request) error {
			return http.ErrUseLastResponse
		},
	}

	file, err := os.Open(s.config.Wordlist)
	if err != nil {
		fmt.Printf("Error opening wordlist: %v\n", err)
		return
	}
	defer file.Close()
	scanner := bufio.NewScanner(file)
	for scanner.Scan() {
		s.wordlist = append(s.wordlist, scanner.Text())
	}

	var wg sync.WaitGroup
	for _, uri := range s.config.URIs {
		if !strings.HasSuffix(uri, "/") {
			uri += "/"
		}
		wg.Add(1)
		go func(u string) {
			defer wg.Done()
			s.scanDirectory(u, 0)
		}(uri)
	}
	wg.Wait()

	s.report()
}

func (s *Scanner) report() {
	if s.config.JSONFile != "" {
		data, _ := json.Marshal(s.results)
		os.WriteFile(s.config.JSONFile, data, 0644)
	}
	if s.config.XMLFile != "" {
        xmlRes := XMLResult{Results: s.results}
		data, _ := xml.Marshal(xmlRes)
        header := []byte("<?xml version=\"1.0\" encoding=\"UTF-8\"?>\n")
        output := strings.ReplaceAll(string(data), "></path>", "/>")
        output = strings.ReplaceAll(output, "<path", "\n<path")
        output = strings.ReplaceAll(output, "</dirble_scan>", "\n</dirble_scan>")
		os.WriteFile(s.config.XMLFile, append(header, []byte(output)...), 0644)
	}
}

func main() {
	conf := parseArgs()
	if len(conf.URIs) == 0 {
		fmt.Println("No URI provided")
		os.Exit(1)
	}

	scanner := &Scanner{config: conf}
    scanner.run()
}
