	Throttle           int
	ScanListable       bool
	MaxRecursionDepth  int
	DisableRecursion   bool
	ScrapeListable     bool
	UserAgent          string
	Cookies            []string
	Headers            []string
	Silent             bool
	Verbose            int
	CodeBlacklist      []int
	CodeWhitelist      []int
	NoColor            bool
}

type Scanner struct {
	config Config
	client *http.Client
	results []Result
	resultsMutex sync.Mutex
	wordlist []string
	visited sync.Map
}

func parseArgs() Config {
	conf := Config{
		Verb:              "GET",
		Timeout:           5,
		MaxErrors:         5,
		MaxThreads:        10,
		WordlistSplit:     3,
		MaxRecursionDepth: 100,
	}

	args := os.Args[1:]
	for i := 0; i < len(args); i++ {
		arg := args[i]
		switch arg {
		case "-h", "--help":
			printHelp()
			os.Exit(0)
		case "-V", "--version":
			fmt.Println("Dirble 1.4.2 (commit d520c82, build 2026-04-17)")
			os.Exit(0)
		case "-u", "--uri", "--url":
			i++
			if i < len(args) { conf.URIs = append(conf.URIs, args[i]) }
		case "-U", "--uri-file", "--url-file":
			i++
			if i < len(args) {
				content, _ := os.ReadFile(args[i])
				lines := strings.Split(string(content), "\n")
				for _, line := range lines {
					line = strings.TrimSpace(line)
					if line != "" { conf.URIs = append(conf.URIs, line) }
				}
			}
		case "-w", "--wordlist":
			i++
			if i < len(args) { conf.Wordlist = args[i] }
		case "-x", "--extensions":
			i++
			if i < len(args) {
				exts := strings.Split(args[i], ",")
				conf.Extensions = append(conf.Extensions, exts...)
			}
		case "-p", "--prefixes":
			i++
			if i < len(args) {
				prefs := strings.Split(args[i], ",")
				conf.Prefixes = append(conf.Prefixes, prefs...)
			}
		case "-f", "--force-extension":
			conf.ForceExtension = true
		case "--ext-sub":
			conf.ExtSub = true
		case "-k", "--ignore-cert":
			conf.IgnoreCert = true
		case "--timeout":
			i++
			if i < len(args) { conf.Timeout, _ = strconv.Atoi(args[i]) }
		case "-t", "--max-threads":
			i++
			if i < len(args) { conf.MaxThreads, _ = strconv.Atoi(args[i]) }
		case "-T", "--wordlist-split":
			i++
			if i < len(args) { conf.WordlistSplit, _ = strconv.Atoi(args[i]) }
		case "-z", "--throttle":
			i++
			if i < len(args) { conf.Throttle, _ = strconv.Atoi(args[i]) }
		case "--json-file", "--oJ":
			i++
			if i < len(args) { conf.JSONFile = args[i] }
		case "--xml-file", "--oX":
			i++
			if i < len(args) { conf.XMLFile = args[i] }
		case "-o", "--output-file", "--oN":
			i++
			if i < len(args) { conf.OutputFile = args[i] }
		case "-v":
			conf.Verbose++
		case "-vv":
			conf.Verbose += 2
		case "--verbose":
			conf.Verbose++
		case "-S", "--silent":
			conf.Silent = true
		case "-r", "--disable-recursion":
			conf.DisableRecursion = true
		case "--max-recursion-depth":
			i++
			if i < len(args) { conf.MaxRecursionDepth, _ = strconv.Atoi(args[i]) }
		case "-l", "--scan-listable":
			conf.ScanListable = true
		case "--scrape-listable":
			conf.ScrapeListable = true
		case "--no-color":
			conf.NoColor = true
		case "-B", "--code-blacklist":
			i++
			if i < len(args) {
				codes := strings.Split(args[i], ",")
				for _, c := range codes {
					ci, _ := strconv.Atoi(c)
					conf.CodeBlacklist = append(conf.CodeBlacklist, ci)
				}
			}
		case "-W", "--code-whitelist":
			i++
			if i < len(args) {
				codes := strings.Split(args[i], ",")
				for _, c := range codes {
					ci, _ := strconv.Atoi(c)
					conf.CodeWhitelist = append(conf.CodeWhitelist, ci)
				}
			}
		case "-a", "--user-agent":
			i++
			if i < len(args) { conf.UserAgent = args[i] }
		case "-c", "--cookie":
			i++
			if i < len(args) { conf.Cookies = append(conf.Cookies, args[i]) }
		case "-H", "--header":
			i++
			if i < len(args) { conf.Headers = append(conf.Headers, args[i]) }
		case "--verb":
			i++
			if i < len(args) { conf.Verb = strings.ToUpper(args[i]) }
		default:
			if !strings.HasPrefix(arg, "-") {
				conf.URIs = append(conf.URIs, arg)
			}
		}
	}

	if conf.Wordlist == "" {
		exe, _ := os.Executable()
		dir := strings.TrimSuffix(exe, "executable")
		if dir == "" { dir = "./" }
		conf.Wordlist = dir + "dirble_wordlist.txt"
	}

	return conf
}

